function describeError(error: unknown): string {
    if (error instanceof Error) return `${error.name}: ${error.message}`   // 1) instanceof
    if (typeof error === "string") return error                           // 2) typeof
    if (typeof error === "object" && error !== null && "code" in error) {
        return `kod: ${String(error.code)}`                                // 3) in operatori
    }
    return "noma'lum xato"
}

