type SafeResult<T> = [T, null] | [null, Error]

async function safe<T>(promise: Promise<T>): Promise<SafeResult<T>> {
    try {
        return [await promise, null]
    } catch (error) {
        return [null, error instanceof Error ? error : new Error(String(error))]
    }
}

async function main() {
    const [data, error] = await safe(Promise.resolve({ id: 1, name: "Ali" }))
    if (error) console.log("Xato:", error.message)
    else console.log("Ma'lumot:", data)

    const [data2, error2] = await safe(Promise.reject(new Error("Server ishlamayapti")))
    if (error2) console.log("Xato:", error2.message)
    else console.log("Ma'lumot:", data2)
}
main()

