const wait = (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms))

async function retry<T>(task: (attempt: number) => Promise<T>, attempts: number): Promise<T> {
    let lastError: unknown
    for (let attempt = 1; attempt <= attempts; attempt++) {
        try {
            return await task(attempt)
        } catch (error) {
            lastError = error
            const delay = 2 ** (attempt - 1)
            console.log(`${attempt}-urinish yiqildi, ${delay} ms kutamiz`)
            await wait(delay)
        }
    }
    throw new Error(`${attempts} urinishdan keyin ham bo'lmadi`, { cause: lastError })
}

