function expectThrows<T extends Error>(action: () => unknown, ErrorType: new (...args: never[]) => T): T {
    try {
        action()
    } catch (error) {
        if (error instanceof ErrorType) return error
        throw new Error(`Kutilgan tur: ${ErrorType.name}, lekin boshqa xato keldi`, { cause: error })
    }
    throw new Error(`${ErrorType.name} kutilgan edi, lekin xato otilmadi`)
}

