type Result<T, E = Error> =
    | { ok: true; value: T }
    | { ok: false; error: E }

function parseAge(input: string): Result<number, string> {
    const age = Number(input)
    if (!Number.isInteger(age)) return { ok: false, error: "Butun son kiriting" }
    if (age < 0 || age > 120) return { ok: false, error: "Yosh 0-120 oralig'ida bo'lishi kerak" }
    return { ok: true, value: age }
}

