type LoginError =
    | { kind: "not_found" }
    | { kind: "wrong_password"; attemptsLeft: number }
    | { kind: "locked"; until: string }

function messageFor(error: LoginError): string {
    switch (error.kind) {
        case "not_found": return "Bunday foydalanuvchi yo'q"
        case "wrong_password": return `Parol xato, ${error.attemptsLeft} ta urinish qoldi`
        case "locked": return `Hisob ${error.until} gacha bloklangan`
        default: {
            const unreachable: never = error    // yangi kind qo'shilsa — shu yerda kompilyatsiya xatosi
            return unreachable
        }
    }
}

type Ok<T> = { ok: true; value: T }

function unwrap<T, E>(result: Result<T, E>): T {
    if (result.ok) return result.value
    throw new Error("unwrap xato natijada chaqirildi", { cause: result.error })
}

function assertOk<T, E>(result: Result<T, E>): asserts result is Ok<T> {
    if (!result.ok) throw new Error("Natija xato", { cause: result.error })
}

function show(result: Result<number, string>) {
    assertOk(result)
    console.log(result.value)     // assertOk dan keyin result: Ok<number>
}

function all<T, E>(results: Result<T, E>[]): Result<T[], E> {
    const values: T[] = []
    for (const result of results) {
        if (!result.ok) return result      // birinchi xatoda to'xtaymiz
        values.push(result.value)
    }
    return ok(values)
}

