type Validation<T> = { ok: true; value: T } | { ok: false; errors: string[] }

function validateUser(input: { name: string; email: string; age: number }): Validation<typeof input> {
    const errors: string[] = []
    if (input.name.trim().length < 2) errors.push("Ism juda qisqa")
    if (!input.email.includes("@")) errors.push("Email noto'g'ri")
    if (input.age < 18) errors.push("18 yoshdan katta bo'lishi kerak")
    return errors.length ? { ok: false, errors } : { ok: true, value: input }
}

