type Validated<T> = { [K in keyof T]: Result<T[K], string> }
type FormErrors = Partial<Record<keyof Form, string>>

function validateForm(input: Form): Result<Form, FormErrors> {
    const fields: Validated<Form> = {
        name: input.name.length >= 2 ? ok(input.name) : err("juda qisqa"),
        age: input.age >= 18 ? ok(input.age) : err("18 dan kichik"),
    }

    if (fields.name.ok && fields.age.ok) return ok({ name: fields.name.value, age: fields.age.value })

    const errors: FormErrors = {}
    if (!fields.name.ok) errors.name = fields.name.error
    if (!fields.age.ok) errors.age = fields.age.error
    return err(errors)
}

