    static ok<T>(v: T) { return new Result<T>(true, v) }
    static err<T>(e: string) { return new Result<T>(false, undefined, e) }
    map<U>(f: (x: T) => U): Result<U> { return this.ok ? Result.ok(f(this.v as T)) : Result.err<U>(this.error!) }
    unwrapOr(d: T): T { return this.ok ? (this.v as T) : d }
}
