type CallError = { message: string; retryable: boolean }

function retryWhileRetryable<T>(
    action: (attempt: number) => Result<T, CallError>,
    maxAttempts: number,
): Result<T, CallError> {
    let result = action(1)
    for (let attempt = 2; !result.ok && result.error.retryable && attempt <= maxAttempts; attempt++) {
