type Res<T> = { ok: true; value: T } | { ok: false; error: string }
const port = (v: string | undefined): Res<number> => (v && /^\d+$/.test(v) ? { ok: true, value: Number(v) } : { ok: false, error: `PORT noto'g'ri: ${v}` })
const host = (v: string | undefined): Res<string> => (v ? { ok: true, value: v } : { ok: false, error: "HOST yo'q" })
function loadCfg(env: Record<string, string | undefined>): Res<{ port: number; host: string }> {
    const p = port(env.PORT); if (!p.ok) return p
    const h = host(env.HOST); if (!h.ok) return h
    return { ok: true, value: { port: p.value, host: h.value } }
}
console.log(loadCfg({ PORT: "8080", HOST: "localhost" }), loadCfg({ PORT: "abc", HOST: "x" }), loadCfg({ PORT: "80" }))

type Result<T, E> = { ok: true; value: T } | { ok: false; error: E }

type ValueOf<R> = R extends { ok: true; value: infer T } ? T : never
type ErrorOf<R> = R extends { ok: false; error: infer E } ? E : never

function parseAge(text: string): Result<number, "empty" | "nan"> {
    if (text === "") return { ok: false, error: "empty" }
    const age = Number(text)
    return Number.isNaN(age) ? { ok: false, error: "nan" } : { ok: true, value: age }
}

type Age = ValueOf<ReturnType<typeof parseAge>>          // number
type AgeError = ErrorOf<ReturnType<typeof parseAge>>     // "empty" | "nan"

const age: Age = 30
const reasons: AgeError[] = ["empty", "nan"]
console.log(age, reasons)

type Result<T, E> = { ok: true; value: T } | { ok: false; error: E }

const fromNullable = <T, E>(value: T | null | undefined, error: E): Result<T, E> =>
    value === null || value === undefined ? { ok: false, error } : { ok: true, value }

const users = new Map([[1, "Ali"], [2, "Vali"]])

console.log(fromNullable(users.get(1), "topilmadi"))
console.log(fromNullable(users.get(5), "topilmadi"))
console.log(fromNullable([3, 8, 12].find(n => n > 10), "10 dan katta son yo'q"))

examples.output:
{ ok: true, value: 'Ali' }
{ ok: false, error: 'topilmadi' }
